def build() -> None:
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
    from scripts.locales_extra import T2
    from scripts.locales_v3 import T3
    from scripts.locales_v4 import OVERRIDE, T4
    from scripts.locales_v5 import OVERRIDE5, T5
    from scripts.locales_v6 import T6
    from scripts.locales_v7 import OVERRIDE7, T7
    from scripts.locales_v8 import OVERRIDE8, T8
    from scripts.locales_v9 import OVERRIDE9, T9
    parts = [T, T2, T3, T4, T5, T6, T7, T8, T9]
    dup = {k for i, a in enumerate(parts) for b in parts[i + 1:] for k in set(a) & set(b)}
    assert not dup, f"takroriy kalitlar: {sorted(dup)}"
    for extra in parts[1:]:
        T.update(extra)
    missing = set(OVERRIDE) - set(T)
    assert not missing, f"OVERRIDE'dagi kalit topilmadi: {sorted(missing)}"
    T.update(OVERRIDE)
    missing = set(OVERRIDE5) - set(T)
    assert not missing, f"OVERRIDE5'dagi kalit topilmadi: {sorted(missing)}"
    T.update(OVERRIDE5)
    missing = set(OVERRIDE7) - set(T)
    assert not missing, f"OVERRIDE7'dagi kalit topilmadi: {sorted(missing)}"
    T.update(OVERRIDE7)
    missing = set(OVERRIDE8) - set(T)
    assert not missing, f"OVERRIDE8'dagi kalit topilmadi: {sorted(missing)}"
    T.update(OVERRIDE8)
    missing = set(OVERRIDE9) - set(T)
    assert not missing, f"OVERRIDE9'dagi kalit topilmadi: {sorted(missing)}"
    T.update(OVERRIDE9)
    OUT.mkdir(parents=True, exist_ok=True)
    for i, lang in enumerate(("uz", "ru", "en")):
        data = {k: (uz_typo(v[0]) if lang == "uz" else v[i]) for k, v in sorted(T.items())}
        (OUT / f"{lang}.json").write_text(json.dumps(data, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"{len(T)} ta kalit × 3 til -> {OUT}")


if __name__ == "__main__":
    build()
    sys.exit(0)
